div.script:

document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.kt_itin2_activities_toggle').forEach(function (btn) {
        var target = document.querySelector(btn.getAttribute('data-bs-target'));
        if (!target) { return; }
        var label = btn.querySelector('.kt_itin2_show_label');
        var setLabel = function (open) {
            label.innerHTML = (open ? 'Hide' : 'Show') + ' <i class="fa fa-chevron-' + (open ? 'up' : 'down') + '"></i>';
        };
        target.addEventListener('shown.bs.collapse', function () { setLabel(true); });
        target.addEventListener('hidden.bs.collapse', function () { setLabel(false); });
    });
});


document.addEventListener('DOMContentLoaded', function () {
    var wrap = document.getElementById('kt_season_table');
    if (!wrap) { return; }
    var tabs = wrap.querySelectorAll('.kt_season_tab');
    tabs.forEach(function (tab) {
        tab.addEventListener('click', function () {
            tabs.forEach(function (t) { t.classList.toggle('active', t === tab); });
            var key = tab.getAttribute('data-season-tab');
            wrap.querySelectorAll('[data-season-panel]').forEach(function (panel) {
                panel.hidden = panel.getAttribute('data-season-panel') !== key;
            });
        });
    });
});


document.addEventListener('DOMContentLoaded', function () {
    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    document.querySelectorAll('.kt_map_container[data-points]').forEach(function (mapEl) {
        if (mapEl.dataset.leafletInit) { return; }
        var points = JSON.parse(mapEl.dataset.points || '[]');
        if (!points.length) { return; }
        mapEl.dataset.leafletInit = '1';
        var map = L.map(mapEl.id).setView([points[0].lat, points[0].lng], 6);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; OpenStreetMap contributors',
            maxZoom: 18
        }).addTo(map);
        var latlngs = [];
        points.forEach(function (p, index) {
            var marker = L.marker([p.lat, p.lng]).addTo(map);
            marker.bindPopup('<strong>' + (index + 1) + '. ' + p.name + '</strong>');
            latlngs.push([p.lat, p.lng]);
        });
        var route = L.polyline(latlngs, {color: '#C1440E', weight: 3, dashArray: '6 8'}).addTo(map);
        map.fitBounds(latlngs, {padding: [40, 40]});

        // Draw the route in as the map scrolls into view, rather than
        // showing it fully drawn immediately - purely cosmetic, so any
        // failure to get the path element (e.g. a future Leaflet change)
        // just leaves the line fully visible with no animation.
        if (reduceMotion || !('IntersectionObserver' in window)) { return; }
        var path = route.getElement && route.getElement();
        if (!path || typeof path.getTotalLength !== 'function') { return; }
        var length = path.getTotalLength();
        path.style.strokeDasharray = length;
        path.style.strokeDashoffset = length;
        var observer = new IntersectionObserver(function (entries) {
            if (!entries[0].isIntersecting) { return; }
            observer.disconnect();
            path.getBoundingClientRect(); // force reflow before transitioning
            path.style.transition = 'stroke-dashoffset 1.6s ease';
            path.style.strokeDashoffset = '0';
        }, {threshold: 0.3});
        observer.observe(mapEl);
    });
});

form.script:

document.addEventListener('DOMContentLoaded', function () {
    var picker = document.getElementById('kt_traveler_picker');
    if (!picker) { return; }
    var trigger = document.getElementById('kt_traveler_trigger');
    var panel = document.getElementById('kt_traveler_panel');
    var doneBtn = document.getElementById('kt_traveler_done');
    var counts = {adults: 2, children: 0, infants: 0};
    var MIN = {adults: 1, children: 0, infants: 0};
    var MAX = {adults: 12, children: 8, infants: 6};

    function refresh() {
        var parts = [counts.adults + ' adult' + (counts.adults !== 1 ? 's' : '')];
        if (counts.children) { parts.push(counts.children + ' child' + (counts.children !== 1 ? 'ren' : '')); }
        if (counts.infants) { parts.push(counts.infants + ' infant' + (counts.infants !== 1 ? 's' : '')); }
        document.getElementById('kt_traveler_summary').textContent = parts.join(', ');
        ['adults', 'children', 'infants'].forEach(function (key) {
            document.getElementById('kt_count_' + key).textContent = counts[key];
            document.getElementById('kt_input_' + key).value = counts[key];
        });
    }

    picker.querySelectorAll('.kt_stepper_btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            var key = btn.dataset.target;
            var delta = btn.dataset.action === 'inc' ? 1 : -1;
            var next = counts[key] + delta;
            if (next < MIN[key] || next > MAX[key]) { return; }
            counts[key] = next;
            refresh();
        });
    });

    trigger.addEventListener('click', function (e) {
        e.preventDefault();
        panel.hidden = !panel.hidden;
        trigger.classList.toggle('kt_traveler_trigger_active', !panel.hidden);
    });

    doneBtn.addEventListener('click', function () {
        panel.hidden = true;
        trigger.classList.remove('kt_traveler_trigger_active');
    });

    document.addEventListener('click', function (e) {
        if (!picker.contains(e.target)) {
            panel.hidden = true;
            trigger.classList.remove('kt_traveler_trigger_active');
        }
    });

    refresh();
});
